<script setup lang="ts">
import type { TraditionDetail } from '~/types/traditions'
import { displayDate } from '~/utils/provenance'
defineProps<{ tradition: TraditionDetail; schoolName: string; canEdit: boolean; canVersion: boolean; pending?: boolean }>()
defineEmits<{ edit: []; annual: []; archive: [] }>()
</script>
<template><div class="tradition-detail-content"><header class="tradition-heading"><p class="muted">Школьная традиция · ежегодное событие</p><h1>{{ tradition.title }}</h1><p class="muted">{{ schoolName }}</p><div class="tradition-meta"><UiBadge :tone="tradition.is_archived ? 'neutral' : 'success'">{{ tradition.is_archived ? 'В архиве' : 'Активная традиция' }}</UiBadge><span>Год основания: {{ tradition.established_year ?? 'не указан' }}</span></div></header><UiCard class="tradition-concept"><h2>Концепция мероприятия</h2><p class="tradition-description">{{ tradition.description }}</p><p class="tradition-current">{{ tradition.active_version ? `Текущая версия: ${tradition.active_version.academic_year}` : 'Ежегодные версии ещё не созданы' }}</p></UiCard><div class="tradition-actions"><UiButton v-if="canVersion" :disabled="pending" @click="$emit('annual')">Создать ежегодную версию</UiButton><UiButton v-if="canEdit" variant="secondary" :disabled="pending" @click="$emit('edit')">Редактировать сведения</UiButton><UiButton v-if="canEdit && !tradition.is_archived" variant="secondary" :disabled="pending" @click="$emit('archive')">Архивировать традицию</UiButton></div><section class="tradition-history"><h2>История ежегодных версий</h2><p class="muted">Каждый выпуск сохраняется отдельно. Сведения прошлых лет не перезаписываются.</p><UiCard v-if="!tradition.versions.length"><UiState kind="empty" title="История пока пуста" description="Создайте первую ежегодную версию этой традиции." /></UiCard><article v-for="version in tradition.versions" :key="version.id" class="tradition-version" :class="{ 'tradition-version--current': version.id === tradition.active_version?.id }"><h3>{{ version.academic_year }}</h3><NuxtLink :to="{ path: '/constructor', query: { school: tradition.school_id, tradition_version_id: version.id } }" class="text-button">Создать мероприятие по этой версии →</NuxtLink><p :class="version.id === tradition.active_version?.id ? 'tradition-current' : 'muted'">{{ version.id === tradition.active_version?.id ? 'Текущая по порядку создания' : 'Историческая версия' }} · {{ displayDate(version.created_at) }}</p><p class="tradition-description">{{ version.notes || 'Заметки не добавлены' }}</p><details v-if="version.parameters_snapshot"><summary>Сохранённые параметры</summary><pre>{{ JSON.stringify(version.parameters_snapshot, null, 2) }}</pre></details></article></section><UiAlert tone="warning"><strong>При создании новой версии</strong><p>Концепция, дата и участники сохраняются отдельно. Источники и культурные факты необходимо проверить повторно.</p></UiAlert><p class="muted">Создано: {{ displayDate(tradition.created_at) }} · Сведения обновлены: {{ displayDate(tradition.updated_at) }}</p></div></template>
